SELECT CASE WHEN o.discount >= 0.36 THEN 'high' WHEN o.discount >= 0.17 THEN 'mid' ELSE 'low' END AS discount_bucket, o.status, SUM(CASE WHEN s.carrier = 'Kerry' THEN s.cost ELSE 0 END) AS kerry_cost FROM shipments s INNER JOIN orders o ON o.id = s.order_id LEFT OUTER JOIN stores st ON o.store_id = st.id GROUP BY CASE WHEN o.discount >= 0.36 THEN 'high' WHEN o.discount >= 0.17 THEN 'mid' ELSE 'low' END, o.status;
